from library_audit import *
from collections import Counter
def run():
    summary=json.loads((ROOT/'summary.json').read_text(encoding='utf-8'));index=json.loads((ROOT/'index.json').read_text(encoding='utf-8'));audits=read('fulltext_library/license_audit.csv')+read('fulltext_library/new_artifact_audit.csv')+read('fulltext_library/public_pdf_audit.csv');lookup={r['paper_id']:r for r in index}
    reasons=Counter(a['reason'] for a in audits if a['decision']!='public_allowed');tex=read('fulltext_library/latex_acquisition.csv');core=[];attempts=read('fulltext_library/core_acquisition_attempts.csv')
    for pid in CORE:
        r=lookup[pid];aa=[a for a in attempts if a['paper_id']==pid]
        core.append(dict(paper_id=pid,title=r['title'],doi=r['doi'],fulltext_status=r['status'],downloaded_main=sum(a['artifact_type']=='main' and a['status']=='downloaded' for a in aa),downloaded_supplement=sum(a['artifact_type']=='supplement' and a['status']=='downloaded' for a in aa),public_pdf=';'.join(r['public_pdf']),reason='license_not_confirmed; keep local' if r['status']=='local_only' else '; '.join(sorted(set(a.get('error','') for a in aa if a.get('error')))) or 'not located in authorized sources',source_url=r['original_url']))
    csvwrite('fulltext_library/core_status.csv',core)
    private=read('fulltext_library/local_conversion_manifest.csv') if (ROOT/'local_conversion_manifest.csv').exists() else []
    report=['# 全文库构建与许可核查报告','',f'日期：{stamp()}。研究检索截止仍为2026-11-26。','', '本轮核查上一批208个有全文的paper_id条目及其补充/版本文件，并继续获取13篇核心文献。已建立类别/paper_id目录，不修改既有论文、假设、估计方法或模拟实验。','', '## 实际成果','',f"- 上一批208个paper_id全部纳入逐文件许可审计，共213条paper_id/哈希记录。发现两组跨ID的同哈希文件，见duplicate_files.json；因此208不等于208份不同PDF。",f"- 共{summary['entries']}个入口目录；{summary['public_entries']}个条目有公开全文、{summary['local_only_entries']}个条目仅本地可读、{summary['not_acquired_entries']}篇核心正文仍未取得。",f"- 公开原始文件按SHA去重：{summary['public_original_pdf']}份PDF、{summary['public_original_xml']}份JATS XML；配套{summary['public_markdown']}份Markdown、{summary['public_txt']}份TXT。",f"- 保留{summary['original_tex_files']}个原始.tex文件，来自{sum(t['status']=='downloaded_original_tex' for t in tex)}个arXiv版本源包；{sum(t['status']!='downloaded_original_tex' for t in tex)}个已许可arXiv版本源入口未取得TeX，见latex_acquisition.csv。",f"- 本地受限PDF另外生成{len(private)}条逐页Markdown/TXT转换记录，全部位于local_private/，未上传全文。",f"- {summary['reading_notes']}份原创版本/定位/精读准备札记；{summary['formula_flagged_pages']}个公开PDF页面标有数学核对提示。未声称已逐式人工复核。",'','## 数学与分页','', '所有原始PDF/XML与作者TeX均按字节保留，校验SHA256。PDF Markdown/TXT按物理页分段，page_map.json同时给出GitHub读取需要的行号范围；印刷页码候选与PDF标签单独记录。定理、引理、假设、证明等实际观察标签及页码/行号见theorem_proof_locator.csv。公式未被猜测性重写或修正。','', '仅有XML的条目没有伪造PDF分页。JATS的原始TeX-math和MathML保留在转换稿及original_formula_markup.json中。原始PDF文件仍在获取失败的XML条目，保留失败来源与原因，不能把XML称为PDF。','', '## 未公开原因','', 'arXiv默认非独占分发许可未授予第三方再分发权；作者主页或机构存档公开可读也不自动授予上传权。下列为逐文件记录的原因分布，不能作为独立论文数量相加：','', '```json',json.dumps(dict(reasons),ensure_ascii=False,indent=2),'```','','原始材料保持各自CC BY / BY-NC / BY-NC-ND / BY-NC-SA等条件；本库为非商业学术研究用途。ND文件仅作技术格式转换，原始文件完整保留，不翻译或改写。权利及转换规则见CONVERSION_AND_RIGHTS.md。','', '## 13篇核心文献的本轮状态','','|paper_id|正文|补充新取得|公开PDF|','|---|---|---:|---:|']
    for r in core:report.append(f"|{r['paper_id']}|{r['fulltext_status']}|{r['downloaded_supplement']}|{int(bool(r['public_pdf']))}|")
    report+=['','新取得正文为C01收益—风险约束规则、G02 Cox、G08竞争风险随机森林；G08另取得独立补充。均尚未确认可公开再分发，保存本地。其余10篇仍未取得，具体HTTP/非PDF失败、原文路径见core_acquisition_attempts.csv和core_status.csv。没有绕过付费墙、CAPTCHA、登录或TDM token要求。','', '## 复核与局限','', '完整性校验见validation.json。其检查原始文件哈希、页数及逐页分段、作者TeX字节、索引路径和许可白名单。原PDF页面经抽样渲染检查；未对全部数学公式作视觉逐式审校。OCR未被用来补写没有文本层的页；读者须回原页或作者TeX核对。','', '这些阅读札记是依据实际资料建立的精读准备和定位记录，不是已经完成的理论评述。原始TeX的外部样式、图片和数据没有被自动公开；源码未编译，不能承诺独立编译成功。']
    (ROOT/'REPORT.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
    print(json.dumps(summary,ensure_ascii=False),flush=True)
if __name__=='__main__':run()
